class Solution:
    def countSubstrings(self, s: str) -> int:
        total_palindromic_substrings = 0
        n = len(s)

        def expand_around_center(left: int, right: int) -> int:
            count = 0
            while left >= 0 and right < n and s[left] == s[right]:
                count += 1
                left -= 1
                right += 1
            return count

        for i in range(n):
            total_palindromic_substrings += expand_around_center(i, i)
            total_palindromic_substrings += expand_around_center(i, i + 1)

        return total_palindromic_substrings

